suppressPackageStartupMessages({library(survey);library(haven);library(mice)})
options(survey.lonely.psu='adjust')
root <- '.'; src <- file.path(root,'hpv_sync_20261102'); out <- file.path(root,'clr_unit_audit_20261103')
p <- read.csv(file.path(src,'fixed_HPV_sample_preflight_by_person.csv'))
spec <- data.frame(year=c(2003,2005,2007,2009,2015),file=c('L11_C.xpt','CRP_D.xpt','CRP_E.xpt','CRP_F.xpt','HSCRP_I.xpt'),var=c(rep('LBXCRP',4),'LBXHSCRP'))
audit <- list()
for (i in seq_len(nrow(spec))) {
 x <- read_xpt(file.path('nhanes_raw',spec$file[i])); k <- p$cycle_start==spec$year[i]; q<-p[k,]; y<-x[[spec$var[i]]][match(q$SEQN,x$SEQN)]; z<-y*ifelse(spec$year[i]<2015,10,1)
 stopifnot(all(is.na(y)==is.na(q$CRP_raw)),all(is.na(z)==is.na(q$CRP_mg_L)))
 rawdiff<-max(abs(y-q$CRP_raw),na.rm=TRUE); dif<-max(abs(z-q$CRP_mg_L),na.rm=TRUE);stopifnot(rawdiff<1e-10,dif<1e-10)
 audit[[i]]<-data.frame(cycle=spec$year[i],file=spec$file[i],source_var=spec$var[i],n=nrow(q),observed=sum(!is.na(y)),raw_diff=rawdiff,converted_diff=dif)
}
write.csv(do.call(rbind,audit),file.path(out,'cycle_raw_unit_verification.csv'),row.names=FALSE)
mod<-readRDS(file.path(src,'CLR_complete_case_models.rds')); design<-mod$models$free$survey.design; z<-design$variables
stopifnot(nrow(z)==7089,!anyDuplicated(z$SEQN)); chk<-p$CRP_mg_L[match(z$SEQN,p$SEQN)]
stopifnot(!anyNA(chk),max(abs(chk-z$CRP_mg_L))<1e-10,max(abs(z$r-(log(chk)-log(z$LYMPHOCYTE))))<1e-10,max(abs(z$s-(log(chk)+log(z$LYMPHOCYTE))))<1e-10)
mi<-readRDS(file.path(src,'CLR_MI_diagnostics.rds')); md<-mi$imputation$data; target<-p[p$cycle_start==2015,]; obs<-!is.na(target$CRP_mg_L)
stopifnot(nrow(md)==nrow(target),sum(is.na(md$logCRP))==3,identical(is.na(md$logCRP),is.na(target$CRP_mg_L)),max(abs(md$logCRP[obs]-log(target$CRP_mg_L[obs])))<1e-10)
vals<-read.csv(file.path(src,'CLR_MI_imputed_values.csv')); stopifnot(nrow(vals)==60)
for (j in seq_len(20)) stopifnot(max(abs(exp(complete(mi$imputation,j)$logCRP[!obs])-vals$imputed_CRP_mg_L[vals$imputation==j]))<1e-10)
sub<-design[z$cycle_start %in% c(2003,2005,2007,2009),];sub$variables<-droplevels(sub$variables)
warnings<-character(); free<-formula(mod$models$free); fixed<-formula(mod$models$constrained)
fit<-withCallingHandlers(list(free=svyglm(free,design=sub,family=quasibinomial()),constrained=svyglm(fixed,design=sub,family=quasibinomial())),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})
stopifnot(identical(fit$free$survey.design$variables$SEQN,fit$constrained$survey.design$variables$SEQN),all(is.finite(coef(fit$free))),length(warnings)==0)
tt<-regTermTest(fit$free,~s,method='LRT');ww<-regTermTest(fit$free,~s,method='Wald');est<-2*coef(fit$free)['s'];se<-2*sqrt(vcov(fit$free)['s','s']); crit<-qt(.975,ww$ddf)
res<-data.frame(analysis='2003-2010_CRP_measured_CC',N=nrow(sub$variables),events=sum(sub$variables$HPVnew==1),design_df=degf(sub),D=unname(est),se=unname(se),CI_low=unname(est-crit*se),CI_high=unname(est+crit*se),working_LRT_p=as.numeric(tt$p),warning=paste(warnings,collapse=' | '))
# Multiplying every CRP concentration by a constant shifts r and s by constants;
# with an intercept, fitted slopes and the constraint test should not change.
d2<-sub;d2$variables$r<-d2$variables$r-log(10);d2$variables$s<-d2$variables$s-log(10)
f2<-svyglm(free,design=d2,family=quasibinomial()); t2<-regTermTest(f2,~s,method='LRT')
stopifnot(abs(coef(f2)['s']-coef(fit$free)['s'])<1e-9,abs(as.numeric(t2$p)-as.numeric(tt$p))<1e-8)
sub$variables$logA<-log(sub$variables$CRP_mg_L);sub$variables$logB<-log(sub$variables$LYMPHOCYTE)
direct<-update(free,. ~ . - r - s + logA + logB)
fit_direct<-svyglm(direct,design=sub,family=quasibinomial())
coef2<-coef(fit_direct);vv<-vcov(fit_direct); directD<-coef2['logA']+coef2['logB']
directSE<-sqrt(vv['logA','logA']+vv['logB','logB']+2*vv['logA','logB'])
stopifnot(abs(directD-est)<1e-9,abs(directSE-se)<1e-9)
counts<-aggregate(HPVnew~cycle_start,data=sub$variables,FUN=function(v)c(n=length(v),events=sum(v==1)))
write.csv(data.frame(cycle_start=counts$cycle_start,N=counts$HPVnew[,'n'],events=counts$HPVnew[,'events']),file.path(out,'CLR_2003_2010_by_cycle.csv'),row.names=FALSE)
write.csv(res,file.path(out,'CLR_2003_2010_complete_case.csv'),row.names=FALSE)
write.csv(data.frame(SEQN=sub$variables$SEQN),file.path(out,'CLR_2003_2010_membership.csv'),row.names=FALSE)
saveRDS(list(models=fit,lrt=tt,wald=ww,mg_dL_comparison=f2,direct_components=fit_direct),file.path(out,'CLR_2003_2010_models.rds'))
capture.output(sessionInfo(),file=file.path(out,'sessionInfo.txt'))
print(do.call(rbind,audit));print(res);cat('PASS: raw XPT, saved complete case inputs, MI input and imputed values, and unit-rescaling invariance\n')
